async function notifyWithdrawal(env, origin, to, status, amount, method) {
  if (!to) return false;
  const amt = '$' + Number(amount || 0).toFixed(2);
  const m = String(method || 'upi').toUpperCase();
  let subject, title, body;
  if (status === 'pending') {
    subject = `Withdrawal request received — ${amt}`;
    title = 'Withdrawal request received';
    body = `<p>We have received your withdrawal request for <b>${amt}</b> via <b>${m}</b>.</p>
      <p style="margin:14px 0">${pill('PENDING REVIEW', '#a86b00', '#fdf3e0')}</p>
      <p>It will be reviewed and paid within <b>12 hours</b>. You will get another email as soon as it is processed.</p>`;
  } else if (status === 'approved') {
    subject = `Withdrawal approved — ${amt}`;
    title = 'Withdrawal approved';
    body = `<p>Your withdrawal of <b>${amt}</b> has been approved.</p>
      <p style="margin:14px 0">${pill('APPROVED', '#1d4ed8', '#e8efff')}</p>
      <p>Payment is on its way to your ${m} account.</p>`;
  } else if (status === 'paid') {
    subject = `Payment sent — ${amt}`;
    title = 'Payment sent';
    body = `<p><b>${amt}</b> has been sent to your ${m} account.</p>
      <p style="margin:14px 0">${pill('PAID', '#0f7a52', '#e9faf2')}</p>
      <p>Thanks for using EliteURL. Keep sharing your links!</p>`;
  } else if (status === 'rejected') {
    subject = `Withdrawal not approved — ${amt}`;
    title = 'Withdrawal not approved';
    body = `<p>Your withdrawal request for <b>${amt}</b> was not approved.</p>
      <p style="margin:14px 0">${pill('REJECTED', '#c02b2b', '#fdeeee')}</p>
      <p>The amount has been returned to your confirmed balance. You can request again at any time.</p>`;
  } else return false;
  return sendMail(env, to, subject, mailShell(title, body, origin));
}

// ---------- auth ----------
function cookieHeader(tok) {
  return `${COOKIE}=${tok}; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=${SESSION_DAYS * 86400}`;
}
function readCookie(request, name) {
  const c = request.headers.get('cookie') || '';
  const m = c.match(new RegExp('(?:^|;\\s*)' + name + '=([^;]+)'));
  return m ? m[1] : null;
}
async function currentUser(request, env) {
  const tok = readCookie(request, COOKIE);
  if (tok) {
    const hash = await sha256Hex(tok);
    const s = await env.DB.prepare('SELECT * FROM auth_sessions WHERE token_hash = ? AND expires_at > ?')
      .bind(hash, Math.floor(Date.now() / 1000)).first();
    if (s) {
      const u = await env.DB.prepare('SELECT * FROM users WHERE id = ? AND status = ?').bind(s.user_id, 'active').first();
      if (u) return u;
    }
  }
  const key = request.headers.get('x-api-key');
  if (key && key === env.API_KEY) {
    return env.DB.prepare('SELECT * FROM users WHERE email = ?').bind(ownerEmailOf(env) || 'owner@eliteofficial.in').first();
  }
  return null;
}
async function createSession(env, userId) {
  const tok = [...crypto.getRandomValues(new Uint8Array(32))].map((b) => b.toString(16).padStart(2, '0')).join('');
  await env.DB.prepare('INSERT INTO auth_sessions (id,user_id,token_hash,created_at,expires_at) VALUES (?,?,?,?,?)')
    .bind(crypto.randomUUID(), userId, await sha256Hex(tok),
      Math.floor(Date.now() / 1000), Math.floor(Date.now() / 1000) + SESSION_DAYS * 86400).run();
  return tok;
}

// ---------- main router ----------
// auto cleanup — din mein ek baar, background mein
async function maybeAutoCleanup(env, ctx) {
  try {
    const last = await env.DB.prepare("SELECT value FROM settings WHERE key='last_cleanup'").first();
    const lastTs = last ? Number(last.value) : 0;
    if (Math.floor(Date.now() / 1000) - lastTs < 86400) return;
    const days = await numSetting(env, 'retention_days', 60);
    const job = runCleanup(env, days);
    if (ctx && typeof ctx.waitUntil === 'function') ctx.waitUntil(job);
    else await job;
  } catch (e) {}
}

